// Not working
namespace {

// CatchAtAge_CalculateRecruitment
// IO correctness
TEST_F(CAAEvaluateTestFixture,
       HandlesCorrectInput_CatchAtAge_CalculateRecruitment) {
  // calculating spawning biomass for year 4
  int sb_year = 4;
  int sb_age = 0;
  int sb_i_age_year = sb_year * population->n_ages + sb_age;
  int sb_i_agem1_yearm1 = (sb_year - 1) * population->n_ages + sb_age - 1;

  size_t pop_id = population->GetId();
  auto& dq = catch_at_age_model->GetPopulationDerivedQuantities(pop_id);

  catch_at_age_model->CalculateNumbersAA(population, sb_i_age_year,
                                         sb_i_agem1_yearm1, sb_age);
  for (size_t year = 0; year < n_years; year++) {
    for (size_t age = 0; age < n_ages; age++) {
      int i_age_year = year * population->n_ages + age;
      catch_at_age_model->CalculateMaturityAA(population, i_age_year, year,
                                              age);
    }
  }
  catch_at_age_model->CalculateSpawningBiomass(population, sb_i_age_year,
                                               sb_year, sb_age);

  // calculating phi_0
  double phi_0 = catch_at_age_model->CalculateSBPR0(population);

  // calculating recruitment for year 5
  int r_year = 5;
  int r_age = 0;  // just calculating for age 0
  int r_i_age_year = r_year * population->n_ages + r_age;
  // specifying steepness and rzero values for calculations
  // values from test_population_test_fixture.hpp
  double steep = 0.75;
  double rzero = 1000000;

  // vector for storing expected recruitment
  std::vector<double> expect_recruitment(
      population->n_years * population->n_ages, 0.0);

  /*the log_recruit_dev vector does not include a value for year == 0
  and is of length n_years - 1 where the first position of the vector
  corresponds to the second year of the time series.*/
  expect_recruitment[r_i_age_year] =
      (0.8 * rzero * steep * dq["spawning_biomass"][sb_year]) /
      (0.2 * phi_0 * rzero * (1.0 - steep) +
       dq["spawning_biomass"][sb_year] * (steep - 0.2)) *
      fims_math::exp(population->recruitment->log_recruit_devs[r_year - 1]);

  // calculate recruitment in population module
  catch_at_age_model->CalculateRecruitment(population, r_i_age_year, r_year,
                                           r_year);

  // testing that expected recruitment and population numbers_at_age match
  // The model computes exp(log(mean) + deviation), which rounds differently
  // from mean * exp(deviation) on each platform, so use a relative tolerance.
  EXPECT_NEAR(dq["numbers_at_age"][r_i_age_year],
              expect_recruitment[r_i_age_year],
              1e-10 * expect_recruitment[r_i_age_year]);
  // testing that population numbers_at_age > 0.0
  EXPECT_GT(dq["numbers_at_age"][r_i_age_year], 0.0);
}

// CatchAtAge_CalculateRecruitment
// IO correctness
TEST_F(CAAEvaluateTestFixture,
       HandlesEquilibriumDeviations_CatchAtAge_CalculateRecruitment) {
  auto& dq =
      catch_at_age_model->GetPopulationDerivedQuantities(population->GetId());
  // Under an equilibrium start, recruitment in year y uses deviation
  // y + n_initial_devs because the first n_initial_devs + 1 deviations belong
  // to the first-year age structure.
  size_t n_initial_devs = 3;
  population->initial_numbers = "equilibrium";
  population->n_initial_devs = n_initial_devs;
  population->recruitment->log_recruit_devs.resize(n_years + n_initial_devs);
  for (size_t i = 0; i < population->recruitment->log_recruit_devs.size();
       i++) {
    population->recruitment->log_recruit_devs[i] = 0.1 * (i + 1);
  }
  population->recruitment->log_expected_recruitment.resize(n_years +
                                                           n_initial_devs);

  // Spawning biomass in the year before recruitment sets the mean
  int year = 5;
  for (size_t y = 0; y < n_years; y++) {
    for (size_t age = 0; age < n_ages; age++) {
      catch_at_age_model->CalculateMaturityAA(
          population, y * population->n_ages + age, y, age);
    }
  }
  catch_at_age_model->CalculateSpawningBiomass(
      population, (year - 1) * population->n_ages, year - 1, 0);

  int i_age_year = year * population->n_ages;
  catch_at_age_model->CalculateRecruitment(population, i_age_year, year, year);

  double phi_0 = catch_at_age_model->CalculateSBPR0(population);
  double expected_mean = population->recruitment->evaluate_mean(
      dq["spawning_biomass"][year - 1], phi_0);
  double expected = expected_mean * std::exp(0.1 * (year + n_initial_devs + 1));
  EXPECT_NEAR(dq["numbers_at_age"][i_age_year], expected, 1e-10 * expected);
}
}  // namespace
